{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance assigned a public IP address",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "The instance at count index 1 is assigned a public IP, making it directly addressable from the internet and increasing its exposure to network attacks."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "IMDSv2 is not enforced",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "No metadata options are configured, so the instances may accept IMDSv1 requests, increasing the risk of credential theft through server-side request forgery."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Root volume encryption is not enforced",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "The root EBS volumes do not explicitly enable encryption, so data at rest may be unencrypted depending on the AMI and account-level EBS defaults."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count                       = 3\n  ami                         = data.aws_ami.ubuntu_14_04.image_id\n  instance_type               = \"t2.micro\"\n  associate_public_ip_address = false\n  subnet_id                   = aws_subnet.my_subnet.id\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}\n",
  "fix_summary": "Disabled public IP assignment for all instances, enforced IMDSv2, and enabled encryption for each instance's root EBS volume."
}
